extends Node

const MIN_IOU := 0.90

func _ready():
	run_validation()

func fail(message: String) -> void:
	print("VALIDATION_FAILED: %s" % message)
	get_tree().quit(1)

func base_circle_points() -> Array:
	return [
		Vector2(18, 0),
		Vector2(16.63, 6.89),
		Vector2(12.73, 12.73),
		Vector2(6.89, 16.63),
		Vector2(0, 18),
		Vector2(-6.89, 16.63),
		Vector2(-12.73, 12.73),
		Vector2(-16.63, 6.89),
		Vector2(-18, 0),
		Vector2(-16.63, -6.89),
		Vector2(-12.73, -12.73),
		Vector2(-6.89, -16.63),
		Vector2(0, -18),
		Vector2(6.89, -16.63),
		Vector2(12.73, -12.73),
		Vector2(16.63, -6.89),
	]

func expected_highlights() -> Dictionary:
	return {
		"CoinHighlight1": {"position": Vector2(283.49997, 110.99999), "scale": Vector2(0.8361113, 0.8166667), "polygon": base_circle_points()},
		"CoinHighlight2": {
			"position": Vector2(319.5, 84.0),
			"scale": Vector2(0.7944446, 0.7861112),
			"polygon": [
				Vector2(18, 0),
				Vector2(16.63, 6.89),
				Vector2(12.73, 12.73),
				Vector2(6.89, 16.63),
				Vector2(0, 18),
				Vector2(-6.89, 16.63),
				Vector2(-12.73, 12.73),
